using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using MSFSBlindAssist.Utils.Logging;

namespace MSFSBlindAssist.Aircraft.BBS757;

/// <summary>
/// The BlueBird 757-200's control surface, deserialized from <c>bbs757_control_map.json</c>.
///
/// The JSON is generated by <c>tools/b757-gen/generate_b757_map.py</c> out of the aircraft's own
/// package (its ModelBehaviorDefs and the vendor's click code) and is checked in so the map is
/// reviewable as data. Regenerate it, never hand-edit it, whenever BlueBird ships a build that
/// renames a node or changes a click. A label or a position name is the vendor's own wording (the
/// node's name, the tooltip of a position) unless curation overrides it, which it does where that
/// is missing or wrong: <c>tools/b757-gen/curation.json</c> holds the curated labels and position
/// names, mostly from BlueBird's published variable list (support.bluebirdsim.com/docs/simvars),
/// each with its evidence in the file's notes.
///
/// It ships as an EMBEDDED RESOURCE, not a copied file, for the reason the MD-11's does: a missing
/// copied file would degrade to a 757 with ZERO controls and no obvious cause.
///
/// The JSON also carries the top-level <c>aircraft</c> and <c>package_version</c>, which the app does
/// not read (they tell whoever reviews the map which build it came from); System.Text.Json skips a
/// key with no property.
/// </summary>
public sealed class Bbs757ControlMap
{
    [JsonPropertyName("controls")]
    public List<Bbs757Control> Controls { get; set; } = new();

    /// <summary>Read-only state rows (the APU state, the doors, ...): nothing here is clicked.</summary>
    [JsonPropertyName("status")]
    public List<Bbs757StatusRow> Status { get; set; } = new();

    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true,
    };

    /// <summary>
    /// The memoized map, built ONCE however many threads ask at the same moment
    /// (<see cref="LazyThreadSafetyMode.ExecutionAndPublication"/>). The factory never throws, since
    /// every failure degrades to an empty map, so the Lazy never caches an exception.
    /// </summary>
    private static readonly Lazy<Bbs757ControlMap> Cached =
        new Lazy<Bbs757ControlMap>(LoadEmbedded, LazyThreadSafetyMode.ExecutionAndPublication);

    /// <summary>
    /// Loads (and memoizes) the embedded control map. A missing or malformed resource gives an EMPTY
    /// map and a logged error, never an exception: a broken map must not take the aircraft-switch
    /// path, and with it the whole app, down.
    /// </summary>
    public static Bbs757ControlMap Load() => Cached.Value;

    /// <summary>
    /// Parses a control map from JSON text with the loader's own options, for a test to feed it a small
    /// snippet. Unlike <see cref="Load"/> it lets a malformed document throw.
    /// </summary>
    internal static Bbs757ControlMap Parse(string json) =>
        JsonSerializer.Deserialize<Bbs757ControlMap>(json, Options) ?? new Bbs757ControlMap();

    private static Bbs757ControlMap LoadEmbedded()
    {
        try
        {
            var asm = Assembly.GetExecutingAssembly();
            // Match on the suffix: the resource id comes from the default namespace plus the folder
            // path, so a literal id would break silently on a rename.
            var name = Array.Find(asm.GetManifestResourceNames(),
                n => n.EndsWith("bbs757_control_map.json", StringComparison.OrdinalIgnoreCase));

            if (name == null)
            {
                Log.Error("BBS757", "bbs757_control_map.json embedded resource not found; the 757 will have no controls.");
                return new Bbs757ControlMap();
            }

            using var stream = asm.GetManifestResourceStream(name);
            if (stream == null)
            {
                Log.Error("BBS757", $"Could not open embedded resource {name}; the 757 will have no controls.");
                return new Bbs757ControlMap();
            }

            var map = JsonSerializer.Deserialize<Bbs757ControlMap>(stream, Options) ?? new Bbs757ControlMap();
            Log.Info("BBS757", $"Control map loaded: {map.Controls.Count} controls, {map.Status.Count} status rows.");
            return map;
        }
        catch (Exception ex)
        {
            Log.Error("BBS757", $"Failed to load bbs757_control_map.json: {ex.Message}; the 757 will have no controls.");
            return new Bbs757ControlMap();
        }
    }
}

/// <summary>One clickable cockpit control, as emitted by <c>tools/b757-gen</c>.</summary>
public sealed class Bbs757Control
{
    /// <summary>The node id, e.g. <c>B757_OVHD_BATTERY_BUTTON</c>. Also the MSFSBA variable key.</summary>
    [JsonPropertyName("node")]
    public string Node { get; set; } = string.Empty;

    /// <summary>Cockpit area ("Overhead", "Pedestal", ...): the panel section.</summary>
    [JsonPropertyName("section")]
    public string Section { get; set; } = string.Empty;

    /// <summary>The panel this control sits on within its <see cref="Section"/>.</summary>
    [JsonPropertyName("panel")]
    public string Panel { get; set; } = string.Empty;

    /// <summary>The spoken name, unique within its panel.</summary>
    [JsonPropertyName("label")]
    public string Label { get; set; } = string.Empty;

    /// <summary>One of the <see cref="Bbs757Kinds"/> values.</summary>
    [JsonPropertyName("kind")]
    public string Kind { get; set; } = string.Empty;

    /// <summary>
    /// The L:var carrying this control's position. Null for a <see cref="Bbs757Kinds.Held"/> button
    /// and for a few momentary buttons that have no readable position.
    /// </summary>
    [JsonPropertyName("state_var")]
    public string? StateVar { get; set; }

    /// <summary>The control's positions in order, with the vendor's own names. Empty for a button.</summary>
    [JsonPropertyName("positions")]
    public List<Bbs757Position> Positions { get; set; } = new();

    /// <summary>
    /// The vendor's click code for one press, replayed VERBATIM (never trimmed or "fixed"). Null for
    /// a control that steps with <see cref="Cw"/> and <see cref="Ccw"/>, or that has no click code.
    /// </summary>
    [JsonPropertyName("press")]
    public string? Press { get; set; }

    /// <summary>The vendor's click code for letting go; set on a <see cref="Bbs757Kinds.Held"/> button.</summary>
    [JsonPropertyName("release")]
    public string? Release { get; set; }

    /// <summary>How long a <see cref="Bbs757Kinds.Held"/> button stays down, in milliseconds; 0 elsewhere.</summary>
    [JsonPropertyName("hold_ms")]
    public int HoldMs { get; set; }

    /// <summary>The vendor's click code for one step up (clockwise); null when the control does not step.</summary>
    [JsonPropertyName("cw")]
    public string? Cw { get; set; }

    /// <summary>The vendor's click code for one step down (counterclockwise); null when the control does not step.</summary>
    [JsonPropertyName("ccw")]
    public string? Ccw { get; set; }

    /// <summary>
    /// The node of the guard control that covers this one (e.g. <c>B757_OVHD_SWITCH_GAURD</c>); null for
    /// a control with no guard. The guard must be open before a click on this control takes.
    /// </summary>
    [JsonPropertyName("guard")]
    public string? Guard { get; set; }

    /// <summary>The value the <see cref="Guard"/> control reads while it is closed; null when there is no guard.</summary>
    [JsonPropertyName("guard_closed")]
    public double? GuardClosed { get; set; }

    /// <summary>
    /// The value BlueBird writes to this control when its <see cref="Guard"/> closes (closing the
    /// emergency lights guard forces ARMED), or null when closing the guard leaves it alone.
    /// </summary>
    [JsonPropertyName("close_sets")]
    public double? CloseSets { get; set; }

    /// <summary>
    /// <see cref="Bbs757Variants.Pw"/> or <see cref="Bbs757Variants.Rr"/> for a control only that engine type's
    /// cockpit has (the label ends " (PW)" or " (RR)": the four fuel control switches, the RR electronic engine
    /// control switches and their guards), null for a control both have, and for every control of a map generated
    /// before the field (plan 12 task 8). The panels show a variant's control only on that engine type's aircraft
    /// (<c>Bbs757Variant</c>, which tools/b757-gen/PanelSweep does not link, hence no cref).
    /// </summary>
    [JsonPropertyName("variant")]
    public string? Variant { get; set; }
}

/// <summary>The <c>variant</c> values used by the generator: which engine type's cockpit alone has a control.</summary>
public static class Bbs757Variants
{
    /// <summary>Only the Pratt &amp; Whitney (PW2000) cockpit has the control.</summary>
    public const string Pw = "pw";

    /// <summary>Only the Rolls-Royce (RB211) cockpit has the control.</summary>
    public const string Rr = "rr";
}

/// <summary>One named position of a control or status row.</summary>
public sealed record Bbs757Position(
    [property: JsonPropertyName("value")] double Value,
    [property: JsonPropertyName("label")] string Label);

/// <summary>A read-only state row: a var the panel shows but nothing clicks.</summary>
public sealed class Bbs757StatusRow
{
    /// <summary>The var read for this row, e.g. <c>B757_APU_STATE</c>.</summary>
    [JsonPropertyName("key")]
    public string Key { get; set; } = string.Empty;

    [JsonPropertyName("panel")]
    public string Panel { get; set; } = string.Empty;

    [JsonPropertyName("label")]
    public string Label { get; set; } = string.Empty;

    [JsonPropertyName("positions")]
    public List<Bbs757Position> Positions { get; set; } = new();

    /// <summary>True when a change of this row is spoken without the pilot asking.</summary>
    [JsonPropertyName("announce")]
    public bool Announce { get; set; }
}

/// <summary>The <c>kind</c> discriminator values used by the generator.</summary>
public static class Bbs757Kinds
{
    /// <summary>A momentary push: one press, no held state.</summary>
    public const string Button = "button";

    /// <summary>A push button that latches between two positions.</summary>
    public const string Toggle = "toggle";

    /// <summary>A rotary or multi-position switch, stepped with cw and ccw or set through its state var.</summary>
    public const string Switch = "switch";

    /// <summary>A guard cover over another control.</summary>
    public const string Guard = "guard";

    /// <summary>One choice of a radio-style group, picked by a press that clears its siblings.</summary>
    public const string Select = "select";

    /// <summary>A button that must be held down for <see cref="Bbs757Control.HoldMs"/> before its release.</summary>
    public const string Held = "held";
}
